def max_count(m: int, n: int, ops: List[List[int]]) -> int:
    rows, cols = m, n
    # The cells hit by every operation form the intersection of all rectangles.
    for a, b in ops:
        if a < rows:
            rows = a
        if b < cols:
            cols = b
    return rows * cols

def largest_magic_square(grid: List[List[int]]) -> int:
    m, n = len(grid), len(grid[0])
    # row_ps[r][c] = sum of grid[r][0:c]; col_ps[r][c] = sum of grid[0:r][c]
    row_ps = [[0] * (n + 1) for _ in range(m)]
    col_ps = [[0] * n for _ in range(m + 1)]
    # diag[r][c] = sum along the down right diagonal ending just before (r, c)
    diag = [[0] * (n + 1) for _ in range(m + 1)]
    # anti[r][c] = sum along the down left diagonal ending just before (r, c - 1)
    anti = [[0] * (n + 2) for _ in range(m + 1)]
    for r in range(m):
        for c in range(n):
            v = grid[r][c]
            row_ps[r][c + 1] = row_ps[r][c] + v
            col_ps[r + 1][c] = col_ps[r][c] + v
            diag[r + 1][c + 1] = diag[r][c] + v
            anti[r + 1][c] = anti[r][c + 1] + v

    def is_magic(top: int, left: int, k: int) -> bool:
        target = row_ps[top][left + k] - row_ps[top][left]
        for r in range(top + 1, top + k):
            if row_ps[r][left + k] - row_ps[r][left] != target:
                return False
        for c in range(left, left + k):
            if col_ps[top + k][c] - col_ps[top][c] != target:
                return False
        if diag[top + k][left + k] - diag[top][left] != target:
            return False
        # Anti diagonal from (top, left + k - 1) down to (top + k - 1, left).
        return anti[top + k][left] - anti[top][left + k] == target

    for k in range(min(m, n), 1, -1):
        for top in range(m - k + 1):
            for left in range(n - k + 1):
                if is_magic(top, left, k):
                    return k
    return 1

