def subarray_lcm(nums: List[int], k: int) -> int:
    total = 0
    ending = {}  # lcm value -> number of subarrays ending here with that lcm
    for x in nums:
        nxt = {}
        if k % x == 0:
            nxt[x] = 1  # the subarray [x]
            for val, cnt in ending.items():
                l = val // math.gcd(val, x) * x
                if k % l == 0:  # keep only divisors of k
                    nxt[l] = nxt.get(l, 0) + cnt
        # If x does not divide k, nothing ending here can reach k.
        ending = nxt
        total += ending.get(k, 0)
    return total

def calculate_score(s: str) -> int:
    stacks = [[] for _ in range(26)]  # unmarked positions per letter
    score = 0
    for i, ch in enumerate(s):
        c = ord(ch) - 97
        mirror = 25 - c
        if stacks[mirror]:
            j = stacks[mirror].pop()  # closest unmarked mirror
            score += i - j
        else:
            stacks[c].append(i)
    return score

