def number_of_ways(corridor: str) -> int:
    MOD = 10**9 + 7
    seats = [i for i, c in enumerate(corridor) if c == "S"]
    if not seats or len(seats) % 2:
        return 0
    ways = 1
    # Gap choices between the end of one pair and the start of the next.
    for i in range(2, len(seats), 2):
        ways = ways * (seats[i] - seats[i - 1]) % MOD
    return ways

