def check(args, got, expected):
    seq = args[0]
    if not isinstance(got, list) or len(got) != len(seq):
        return False

    def worst(split):
        bal = [0, 0]
        deepest = 0
        for ch, g in zip(seq, split):
            if isinstance(g, bool) or g not in (0, 1):
                return None
            if ch == "(":
                bal[g] += 1
                deepest = max(deepest, bal[g])
            else:
                bal[g] -= 1
                if bal[g] < 0:
                    return None
        if bal != [0, 0]:
            return None
        return deepest

    mine = worst(got)
    return mine is not None and mine == worst(expected)

