def count_pairs(root: Optional[TreeNode], distance: int) -> int:
    # Post order: reversed pre order puts children before parents.
    order, stack = [], [root]
    while stack:
        node = stack.pop()
        order.append(node)
        for child in (node.left, node.right):
            if child:
                stack.append(child)

    cnt = {}      # node -> list where cnt[d] = leaves exactly d edges below
    good = 0
    for node in reversed(order):
        if not node.left and not node.right:
            here = [0] * (distance + 1)
            here[0] = 1
            cnt[node] = here
            continue
        shifted = []
        for child in (node.left, node.right):
            arr = [0] * (distance + 1)
            if child:
                below = cnt.pop(child)
                arr[1:] = below[:-1]   # one more edge to reach this node
            shifted.append(arr)
        left, right = shifted
        # prefix[j] = leaves in the right subtree within j edges of this node
        prefix = list(itertools.accumulate(right))
        for i in range(1, distance):
            if left[i]:
                good += left[i] * prefix[distance - i]
        cnt[node] = [a + b for a, b in zip(left, right)]
    return good

def min_malware_spread(graph: list[list[int]], initial: list[int]) -> int:
    n = len(graph)
    infected = set(initial)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    # Components made of clean machines only.
    for i in range(n):
        if i in infected:
            continue
        row = graph[i]
        for j in range(i + 1, n):
            if row[j] and j not in infected:
                ri, rj = find(i), find(j)
                if ri != rj:
                    parent[ri] = rj
    size = collections.Counter(find(v) for v in range(n) if v not in infected)

    touches = {}                         # infected machine -> clean components next to it
    spreaders = collections.Counter()    # component -> number of infected neighbours
    for u in initial:
        comps = {find(v) for v in range(n) if graph[u][v] and v not in infected}
        touches[u] = comps
        for c in comps:
            spreaders[c] += 1

    best, best_saved = None, -1
    for u in sorted(initial):
        saved = sum(size[c] for c in touches[u] if spreaders[c] == 1)
        if saved > best_saved:
            best, best_saved = u, saved
    return best

