def min_area_free_rect(points: list[list[int]]) -> float:
    groups = collections.defaultdict(list)
    n = len(points)
    for i in range(n):
        x1, y1 = points[i]
        for j in range(i + 1, n):
            x2, y2 = points[j]
            # Equal midpoint and equal length identify the diagonals of one rectangle.
            key = (x1 + x2, y1 + y2, (x1 - x2) ** 2 + (y1 - y2) ** 2)
            groups[key].append((i, j))

    def dist(a, b):
        return math.hypot(points[a][0] - points[b][0], points[a][1] - points[b][1])

    best = math.inf
    for pairs in groups.values():
        for a in range(len(pairs)):
            p, q = pairs[a]
            for b in range(a + 1, len(pairs)):
                r = pairs[b][0]
                best = min(best, dist(p, r) * dist(q, r))
    return 0.0 if best == math.inf else best

