import re


def basic_calculator_iv(expression: str, evalvars: list[str], evalints: list[int]) -> list[str]:
    known = dict(zip(evalvars, evalints))

    def combine(p, q, sign):
        out = dict(p)
        for term, coef in q.items():
            out[term] = out.get(term, 0) + sign * coef
        return out

    def multiply(p, q):
        out = {}
        for t1, c1 in p.items():
            for t2, c2 in q.items():
                term = tuple(sorted(t1 + t2))
                out[term] = out.get(term, 0) + c1 * c2
        return out

    precedence = {"+": 1, "-": 1, "*": 2}
    operands, operators = [], []

    def apply_top():
        op = operators.pop()
        right, left = operands.pop(), operands.pop()
        if op == "*":
            operands.append(multiply(left, right))
        else:
            operands.append(combine(left, right, 1 if op == "+" else -1))

    for tok in re.findall(r"[a-z]+|[0-9]+|[()+*-]", expression):
        if tok == "(":
            operators.append(tok)
        elif tok == ")":
            while operators[-1] != "(":
                apply_top()
            operators.pop()
        elif tok in precedence:
            while operators and operators[-1] != "(" and precedence[operators[-1]] >= precedence[tok]:
                apply_top()
            operators.append(tok)
        elif tok.isdigit():
            operands.append({(): int(tok)})
        elif tok in known:
            operands.append({(): known[tok]})
        else:
            operands.append({(tok,): 1})
    while operators:
        apply_top()

    poly = operands[0]
    terms = sorted((t for t, c in poly.items() if c != 0), key=lambda t: (-len(t), t))
    return ["*".join([str(poly[t]), *t]) for t in terms]

