def max_rectangle_area(points: list[list[int]]) -> int:
    present = {(x, y) for x, y in points}
    best = -1
    for x1, y1 in points:
        for x2, y2 in points:
            if x1 >= x2 or y1 >= y2:
                continue
            if (x1, y2) not in present or (x2, y1) not in present:
                continue
            # Only the four corners may lie inside or on the border.
            inside = sum(1 for x, y in points if x1 <= x <= x2 and y1 <= y <= y2)
            if inside == 4:
                best = max(best, (x2 - x1) * (y2 - y1))
    return best

