    memo = {}

    def best(v):
        if v <= y:
            return y - v                 # only increments help now
        if v in memo:
            return memo[v]
        res = v - y                      # walk down one step at a time
        for d in (5, 11):
            down = v % d
            res = min(res, down + 1 + best(v // d))           # step down, then divide
