def max_num_edges_to_remove(n: int, edges: list[list[int]]) -> int:
    class DSU:
        def __init__(self, size):
            self.parent = list(range(size + 1))
            self.rank = [0] * (size + 1)
            self.components = size

        def find(self, x):
            parent = self.parent
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(self, a, b):
            ra, rb = self.find(a), self.find(b)
            if ra == rb:
                return False
            if self.rank[ra] < self.rank[rb]:
                ra, rb = rb, ra
            self.parent[rb] = ra
            if self.rank[ra] == self.rank[rb]:
                self.rank[ra] += 1
            self.components -= 1
            return True

    alice, bob = DSU(n), DSU(n)
    kept = 0
    # Shared edges first: one edge can serve both people.
    for t, u, v in edges:
        if t == 3 and alice.union(u, v):
            bob.union(u, v)
            kept += 1
    for t, u, v in edges:
        if t == 1 and alice.union(u, v):
            kept += 1
        elif t == 2 and bob.union(u, v):
            kept += 1
    if alice.components != 1 or bob.components != 1:
        return -1
    return len(edges) - kept

