                queue.append((nr, nc))
    # Land cells never reached are trapped.
    return sum(1 for r in range(m) for c in range(n) if grid[r][c] == 1 and not seen[r][c])

def check_array(nums: list[int], k: int) -> bool:
    n = len(nums)
    ends = [0] * (n + 1)   # ends[j]: amount that stops applying at index j
    active = 0             # amount currently subtracted from index i
    for i, value in enumerate(nums):
        active -= ends[i]
        remaining = value - active
        if remaining < 0:
            return False
        if remaining > 0:
            if i + k > n:
                return False
            active += remaining
            ends[i + k] += remaining
    return True

def preorder_traversal(root: Optional[TreeNode]) -> list[int]:
    if root is None:
        return []
    order = []
    stack = [root]
    while stack:
        node = stack.pop()
        order.append(node.val)
        # Push right first so the left subtree is handled first.
        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)
    return order

def valid_strings(n: int) -> list[str]:
    level = [""]
