def min_distance(houses: list[int], k: int) -> int:
    houses = sorted(houses)
    n = len(houses)
    if k >= n:
        return 0
    prefix = [0]
    for h in houses:
        prefix.append(prefix[-1] + h)
    # cost[i][j]: one mailbox at the median of houses[i..j]
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            m = (i + j) // 2
            left = houses[m] * (m - i) - (prefix[m] - prefix[i])
            right = (prefix[j + 1] - prefix[m + 1]) - houses[m] * (j - m)
            cost[i][j] = left + right
    prev = cost[0][:]                     # one mailbox for houses[0..j]
    for t in range(2, k + 1):
        cur = [0] * n                     # j < t: each house can have its own box
        for j in range(t, n):
            best = prev[j]                # placing an extra box never hurts
            for i in range(t - 1, j + 1):
                c = prev[i - 1] + cost[i][j]
                if c < best:
                    best = c
            cur[j] = best
        prev = cur
    return prev[n - 1]

