def best_team_score(scores: list[int], ages: list[int]) -> int:
    players = sorted(zip(scores, ages))
    size = max(ages)
    tree = [0] * (size + 1)          # Fenwick tree of prefix maxima over ages

    def query(age):
        best = 0
        while age > 0:
            if tree[age] > best:
                best = tree[age]
            age -= age & -age
        return best

    def update(age, value):
        while age <= size:
            if value > tree[age]:
                tree[age] = value
            age += age & -age

    answer = 0
    for score, age in players:
        total = score + query(age)   # best team of earlier players no older than this one
        update(age, total)
        if total > answer:
            answer = total
    return answer

def longest_prefix(s: str) -> str:
    n = len(s)
    pi = [0] * n        # pi[i]: longest proper border of s[:i + 1]
    j = 0
    for i in range(1, n):
        while j and s[i] != s[j]:
            j = pi[j - 1]          # fall back to the next shorter border
        if s[i] == s[j]:
            j += 1
        pi[i] = j
    return s[:pi[-1]]

def is_trionic(nums: list[int]) -> bool:
    n = len(nums)
    i = 0
    while i + 1 < n and nums[i] < nums[i + 1]:
        i += 1
    p = i
    if p == 0:
        return False                    # no first rising phase
    while i + 1 < n and nums[i] > nums[i + 1]:
        i += 1
    q = i
    if q == p or q == n - 1:
        return False                    # no falling phase, or nothing left to rise
    while i + 1 < n and nums[i] < nums[i + 1]:
        i += 1
    return i == n - 1

def max_satisfaction(satisfaction: list[int]) -> int:
    values = sorted(satisfaction)
    total = 0
    suffix = 0               # sum of the dishes chosen so far
    for value in reversed(values):
        if suffix + value <= 0:
            break            # prepending more dishes can no longer help
        suffix += value
        total += suffix      # every chosen dish moves one step later
    return total

def last_stone_weight_ii(stones: list[int]) -> int:
    total = sum(stones)
    reach = 1                       # bit s set means some subset sums to s
    for w in stones:
        reach |= reach << w
    for a in range(total // 2, -1, -1):
        if reach >> a & 1:
            return total - 2 * a
    return total                    # unreachable: a = 0 is always possible

def maximum_minimum_path(grid: list[list[int]]) -> int:
    m, n = len(grid), len(grid[0])
    done = [[False] * n for _ in range(m)]
    heap = [(-grid[0][0], 0, 0)]       # max heap on path score via negation
    while heap:
        neg, r, c = heapq.heappop(heap)
        if done[r][c]:
            continue
        done[r][c] = True
        score = -neg
        if r == m - 1 and c == n - 1:
            return score
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < m and 0 <= nc < n and not done[nr][nc]:
                value = grid[nr][nc]
                heapq.heappush(heap, (-(score if score < value else value), nr, nc))
    return -1  # unreachable: the grid is connected

def shortest_alternating_paths(n: int, red_edges: list[list[int]], blue_edges: list[list[int]]) -> list[int]:
    RED, BLUE = 0, 1
    adj = [[[] for _ in range(n)], [[] for _ in range(n)]]   # adj[color][node]
    for a, b in red_edges:
        adj[RED][a].append(b)
    for u, v in blue_edges:
        adj[BLUE][u].append(v)
    dist = [[-1] * n for _ in range(2)]   # dist[color of last edge][node]
    dist[RED][0] = dist[BLUE][0] = 0
    queue = deque([(0, RED), (0, BLUE)])
    while queue:
        node, last = queue.popleft()
        nxt = 1 - last                        # the next edge must switch color
        for to in adj[nxt][node]:
            if dist[nxt][to] == -1:
                dist[nxt][to] = dist[last][node] + 1
                queue.append((to, nxt))
    answer = []
    for x in range(n):
        r, b = dist[RED][x], dist[BLUE][x]
        if r == -1 or b == -1:
            answer.append(max(r, b))
        else:
            answer.append(min(r, b))
    return answer

def min_array_sum(nums: list[int], k: int, op1: int, op2: int) -> int:
    INF = float("inf")
    dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
    dp[0][0] = 0
    for x in nums:
        half = (x + 1) // 2
        sub = x - k if x >= k else None
        both = None                          # best value using both operations
        if half >= k:
            both = half - k
        if x >= k:
            alt = (x - k + 1) // 2
            both = alt if both is None else min(both, alt)
        nxt = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
        for a in range(op1 + 1):
            row = dp[a]
            for b in range(op2 + 1):
                cur = row[b]
                if cur == INF:
                    continue
                if cur + x < nxt[a][b]:
                    nxt[a][b] = cur + x
                if a < op1 and cur + half < nxt[a + 1][b]:
                    nxt[a + 1][b] = cur + half
                if b < op2 and sub is not None and cur + sub < nxt[a][b + 1]:
                    nxt[a][b + 1] = cur + sub
                if a < op1 and b < op2 and both is not None and cur + both < nxt[a + 1][b + 1]:
                    nxt[a + 1][b + 1] = cur + both
        dp = nxt
    return min(min(row) for row in dp)

