def new21_game(n: int, k: int, max_pts: int) -> float:
    if k == 0 or n >= k - 1 + max_pts:
        return 1.0
    prob = [0.0] * (n + 1)
    prob[0] = 1.0
    window = 1.0          # sum of prob[y] for still drawing totals y in the last max_pts
    answer = 0.0
    for x in range(1, n + 1):
        prob[x] = window / max_pts
        if x < k:
            window += prob[x]     # she keeps drawing from x
        else:
            answer += prob[x]     # she stops at x, and x <= n
        old = x - max_pts
        if 0 <= old < k:
            window -= prob[old]
    return answer

def has_all_codes(s: str, k: int) -> bool:
    need = 1 << k
    if len(s) - k + 1 < need:
        return False                  # not enough windows to cover every code
    mask = need - 1
    seen = bytearray(need)
    code = 0
    found = 0
    for i, ch in enumerate(s):
        code = ((code << 1) | (ch == "1")) & mask
        if i >= k - 1 and not seen[code]:
            seen[code] = 1
            found += 1
            if found == need:
                return True
    return False

def reordered_power_of2(n: int) -> bool:
