def closed_island(grid: list[list[int]]) -> int:
    m, n = len(grid), len(grid[0])
    seen = [[False] * n for _ in range(m)]
    closed = 0
    for sr in range(m):
        for sc in range(n):
            if grid[sr][sc] != 0 or seen[sr][sc]:
                continue
            # Flood fill one island, noting whether it touches the border.
            touches = False
            seen[sr][sc] = True
            stack = [(sr, sc)]
            while stack:
                r, c = stack.pop()
                if r == 0 or c == 0 or r == m - 1 or c == n - 1:
                    touches = True
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 0 and not seen[nr][nc]:
                        seen[nr][nc] = True
                        stack.append((nr, nc))
            if not touches:
                closed += 1
    return closed
